g=[[8,8,8,1,1,8,8,8,8,6],[8,8,8,1,8,8,8,8,8,8],[8]*10,[8]*10,[8]*10,[1,8,8,8,8,8,8,8,8,1],[1,8,8,8,8,8,8,8,8,8],[1,8,8,8,1,1,8,8,8,8],[8,8,8,8,1,1,8,8,8,8],[8,8,8,8,1,1,8,8,8,8]]
R=C=10
# perimeter coordinate list clockwise
per=[]
per += [(0,c) for c in range(C)]
per += [(r,C-1) for r in range(1,R)]
per += [(R-1,c) for c in range(C-2,-1,-1)]
per += [(r,0) for r in range(R-2,0,-1)]
idx=per.index((0,9))
out=[row[:] for row in g]
# paint border segments from 6 each direction until 1
for step in (1,-1):
    i=idx
    while True:
        i=(i+step)%len(per)
        r,c=per[i]
        if g[r][c]==1: break
        if g[r][c]==8: out[r][c]=7
# eligible boundary-touching components = any 1 on boundary; dilation all 1 cells in connected component; but all relevant components by 8 connectivity
from collections import deque
seen=set(); edgecomps=[]
for r in range(R):
 for c in range(C):
  if g[r][c]!=1 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); comp=[]
  while q:
   x,y=q.pop();comp.append((x,y))
   for dx in [-1,0,1]:
    for dy in [-1,0,1]:
     z=(x+dx,y+dy)
     if 0<=z[0]<R and 0<=z[1]<C and g[z[0]][z[1]]==1 and z not in seen: seen.add(z);q.append(z)
  if any(x in (0,R-1) or y in (0,C-1) for x,y in comp):edgecomps.extend(comp)
for r,c in edgecomps:
 for dr in [-1,0,1]:
  for dc in [-1,0,1]:
   x,y=r+dr,c+dc
   if 0<=x<R and 0<=y<C and g[x][y]==8:out[x][y]=7
print('\n'.join(' '.join(map(str,row)) for row in out))

from collections import deque
# 4-connected components of ones touching boundary
seen=set(); edgeones=set()
for r in range(R):
 for c in range(C):
  if g[r][c]!=1 or (r,c) in seen: continue
  q=[(r,c)];seen.add((r,c)); comp=[]
  while q:
   x,y=q.pop();comp.append((x,y))
   for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
    z=x+dx,y+dy
    if 0<=z[0]<R and 0<=z[1]<C and g[z[0]][z[1]]==1 and z not in seen: seen.add(z);q.append(z)
  if any(x in (0,R-1) or y in (0,C-1) for x,y in comp):edgeones.update(comp)
# accessible original 8 cells via 4-neighbor starting adjacent to marker
q=deque(); access=set()
r0,c0=next((r,c) for r in range(R) for c in range(C) if g[r][c]==6)
for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
 x,y=r0+dr,c0+dc
 if 0<=x<R and 0<=y<C and g[x][y]==8:access.add((x,y));q.append((x,y))
while q:
 r,c=q.popleft()
 for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
  x,y=r+dr,c+dc
  if 0<=x<R and 0<=y<C and g[x][y]==8 and (x,y) not in access:access.add((x,y));q.append((x,y))
out2=[row[:] for row in g]
for r,c in access:
 boundary=(r==0 or c==0 or r==R-1 or c==C-1)
 near=any((r+dr,c+dc) in edgeones for dr in (-1,0,1) for dc in (-1,0,1))
 if boundary or near: out2[r][c]=7
print('accessible',len(access),'ones',edgeones)
print('\n'.join(' '.join(map(str,row)) for row in out2))
